policy.member:
(row, input) => {
				const values = record(input);
				if (values.view === "trash") return row.state === "Trashed" && (!values.root || row.root === values.root);
				if (values.view === "favourites") return row.state === "Active" && row.favourite !== false;
				return row.state === "Active";
			}

